    // it was mapped before or it lies in the freshly-allocated run.
    &&& forall|v: nat| #[trigger] new.user.contains_key(v)
            <==> (old.user.contains_key(v) || in_page_run(base, n, v))
    // Pages outside the run are bit-for-bit preserved.
